        {
          id: "s2",
          label: "Agree discharge conditions, including equalization or release timing the plants must provide to protect the system"
        },
        {
          id: "s3",
          label: "Characterize the proposed discharges with the proponents, including peak batch volumes, timing, and strength in general terms"
        },
        {
          id: "s4",
          label: "Price any system work the discharges require under the funding policy and record the agreement before approval"
        },
        {
          id: "s5",
          label: "Check hydraulic capacity for the batch peaks at every element, since average flow alone understates the impact"
        },
        {
          id: "s6",
          label: "Set monitoring at the connections so actual discharge patterns are checked against the agreement from the first month"
        }
